replacements.search:
after.src = img(e.after);
before.src = img(e.before);
bg.src = img(e.after);

replacements.replacement:
after.src = img(e.after);
after.alt = `After: ${e.mode} — ${e.prompt}`;
before.src = img(e.before);
before.alt = `Before: ${e.mode} — ${e.prompt}`;
bg.src = img(e.after);

cmp.addEventListener("pointerdown", (ev) => { dragging = true; cancelAnimationFrame(raf); cmp.setPointerCapture(ev.pointerId); fromPointer(ev); });
cmp.addEventListener("keydown", (ev) => {
  const cur = parseFloat(cmp.style.getPropertyValue("--split")) || 50;
  if (ev.key === "ArrowLeft") { cancelAnimationFrame(raf); setSplit(cur - 5); ev.preventDefault(); }
  else if (ev.key === "ArrowRight") { cancelAnimationFrame(raf); setSplit(cur + 5); ev.preventDefault(); }
  else if (ev.key === "Home") { cancelAnimationFrame(raf); setSplit(0); ev.preventDefault(); }
  else if (ev.key === "End") { cancelAnimationFrame(raf); setSplit(100); ev.preventDefault(); }
});
